template.template_md:
{% block content %}
<h1>Memory Threshold Alert Percentage</h1>
<p class="text-muted">Shows how often the selected memory threshold check was in an alert or failing state based on its recorded history.</p>

{% set check_id = target_check_id|int %}

{% set check_lookup = {} %}
{% for check in data_sources.checks %}
  {% set _ = check_lookup.update({check.id: check}) %}
{% endfor %}

{% set agent_lookup = {} %}
{% for agent in data_sources.agents %}
  {% set _ = agent_lookup.update({agent.id: agent}) %}
{% endfor %}

{% set matching_results = data_sources.checkResults|selectattr('assigned_check_id', 'equalto', check_id)|list %}

{% if matching_results %}
<table class="table table-striped">
  <thead>
    <tr>
      <th>System</th>
      <th>Check Name</th>
      <th>Check Type</th>
      <th>Last Run</th>
      <th>Failing % (history)</th>
      <th>Recorded Points</th>
      <th>Fail Count</th>
    </tr>
  </thead>
  <tbody>
    {% for result in matching_results %}
      {% set related_check = check_lookup.get(result.assigned_check_id) %}
      {% set related_agent = agent_lookup.get(result.agent_id) %}
      {% set stats = namespace(total=0, failing=0) %}
      {% if result.history %}
        {% for point in result.history %}
          {% set stats.total = stats.total + 1 %}
          {% set status_val = point %}
          {% if point is mapping %}
            {% if point.status is defined %}
              {% set status_val = point.status %}
            {% elif point['status'] is defined %}
              {% set status_val = point['status'] %}
            {% endif %}
          {% endif %}
          {% set status_text = (status_val|string)|lower %}
          {% if status_text in ['failing', 'failed', 'error', 'alert', 'warning', 'false', '0', 'critical'] %}
            {% set stats.failing = stats.failing + 1 %}
          {% endif %}
        {% endfor %}
      {% endif %}
      {% set failure_pct = stats.total > 0 and (stats.failing / stats.total * 100) or 0 %}
      <tr>
        <td>{{ related_agent.hostname if related_agent and related_agent.hostname else result.agent_id }}</td>
        <td>{{ related_check.name if related_check and related_check.name else 'Check ' ~ result.assigned_check_id }}</td>
        <td>{{ related_check.check_type if related_check and related_check.check_type else 'memory' }}</td>
        <td>{{ result.last_run if result.last_run else 'N/A' }}</td>
        <td>{{ '%0.1f'|format(failure_pct) }}%</td>
        <td>{{ stats.total }}</td>
        <td>{{ result.fail_count if result.fail_count is not none else 0 }}</td>
      </tr>
    {% endfor %}
  </tbody>
</table>
{% else %}
<div class="alert alert-warning" role="alert">
  No check results were found for check ID {{ check_id }}. Ensure the memory threshold check is assigned and has run at least once.
</div>
{% endif %}

{% endblock %}
